def run(f, opp, r=100):
    out = subprocess.run(['pmars','-b','-r',str(r),'-f',f,opp],capture_output=True,text=True).stdout
    m = re.search(r'Results: (\d+) (\d+) (\d+)', out)
    if not m: return ('ERR',)
    return tuple(map(int, m.groups()))

